// Interview question bank. `answer` holds reference key points — your own notes,
// confidence (1–5) and last-reviewed date are stored in localStorage by question id.
// Add a question by appending an object with a new id (or use "Add question" in the app).
import type { Question, QuestionCategory, StorySeed } from './types';

export const categories: QuestionCategory[] = ['SQL', 'DSA', 'Stats/ML', 'Core CS', 'Case/Guesstimate', 'Behavioural', 'Project deep-dives'];

export const questions: Question[] = [
  // ───────────────────────── SQL ─────────────────────────
  { id: 'q-sql-01', category: 'SQL', sub: 'Concepts', prompt: 'What is the logical order of execution of a SELECT statement?', answer: 'FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT (window functions run here) → DISTINCT → ORDER BY → LIMIT/OFFSET. That is why a SELECT alias can’t be used in WHERE but can be used in ORDER BY, and why you filter on a window function in an outer query/CTE.' },
  { id: 'q-sql-02', category: 'SQL', sub: 'Concepts', prompt: 'WHERE vs HAVING?', answer: 'WHERE filters rows before grouping and cannot reference aggregates. HAVING filters groups after aggregation. Push filters into WHERE whenever possible — fewer rows reach GROUP BY.' },
  { id: 'q-sql-03', category: 'SQL', sub: 'Window functions', prompt: 'ROW_NUMBER vs RANK vs DENSE_RANK — show the difference on tied values.', answer: 'Salaries 100, 100, 90 → ROW_NUMBER 1,2,3 (arbitrary among ties); RANK 1,1,3 (gaps); DENSE_RANK 1,1,2 (no gaps). Use DENSE_RANK for "Nth highest distinct", ROW_NUMBER for dedupe / exactly-N-per-group.' },
  { id: 'q-sql-04', category: 'SQL', sub: 'Patterns', prompt: 'Find the 2nd (and Nth) highest salary — three ways.', answer: '1) SELECT MAX(salary) FROM emp WHERE salary < (SELECT MAX(salary) FROM emp). 2) DENSE_RANK() OVER (ORDER BY salary DESC) = N in a CTE. 3) SELECT DISTINCT salary … ORDER BY salary DESC LIMIT 1 OFFSET N-1. Wrap to return NULL when it doesn’t exist.' },
  { id: 'q-sql-05', category: 'SQL', sub: 'Patterns', prompt: 'How do you find and delete duplicate rows?', answer: 'Find: GROUP BY the business key HAVING COUNT(*) > 1. Delete: WITH d AS (SELECT id, ROW_NUMBER() OVER (PARTITION BY key_cols ORDER BY id) rn FROM t) DELETE FROM t WHERE id IN (SELECT id FROM d WHERE rn > 1). Keeps the lowest id.' },
  { id: 'q-sql-06', category: 'SQL', sub: 'Joins', prompt: 'LEFT JOIN with a condition on the right table in WHERE — what happens?', answer: 'It silently becomes an INNER JOIN: unmatched rows have NULLs on the right, and WHERE right.col = x filters them out. Put the condition in the ON clause to keep all left rows.' },
  { id: 'q-sql-07', category: 'SQL', sub: 'Joins', prompt: 'What is join fan-out and how do you detect / prevent it?', answer: 'Joining to a one-to-many table multiplies rows, so SUMs double-count. Detect: compare COUNT(*) and COUNT(DISTINCT key) before and after the join. Prevent: aggregate the many-side to the join grain first, then join.' },
  { id: 'q-sql-08', category: 'SQL', sub: 'Concepts', prompt: 'UNION vs UNION ALL?', answer: 'UNION removes duplicates (extra sort/hash cost); UNION ALL keeps everything and is faster. Default to UNION ALL unless you need dedupe.' },
  { id: 'q-sql-09', category: 'SQL', sub: 'NULLs', prompt: 'Why can NOT IN return zero rows when the subquery contains a NULL?', answer: 'x NOT IN (1, NULL) expands to x <> 1 AND x <> NULL; the second comparison is UNKNOWN, so the whole predicate is never TRUE. Use NOT EXISTS (or filter NULLs out of the subquery).' },
  { id: 'q-sql-10', category: 'SQL', sub: 'NULLs', prompt: 'COUNT(*) vs COUNT(col) vs COUNT(DISTINCT col)?', answer: 'COUNT(*) counts rows; COUNT(col) counts non-NULL values; COUNT(DISTINCT col) counts distinct non-NULL values. AVG(col) also ignores NULLs — matters when NULL should mean 0.' },
  { id: 'q-sql-11', category: 'SQL', sub: 'Concepts', prompt: 'Correlated subquery vs JOIN vs EXISTS vs CTE — when do you use each?', answer: 'JOIN for combining columns set-wise; EXISTS / NOT EXISTS for semi / anti-joins (stops at first match, NULL-safe); correlated subquery when logic is per row (optimisers often decorrelate); CTEs for readability, reuse and recursion.' },
  { id: 'q-sql-12', category: 'SQL', sub: 'Patterns', prompt: 'Find users who logged in on 3+ consecutive days.', answer: 'Dedupe to (user, date). grp = date − ROW_NUMBER() OVER (PARTITION BY user ORDER BY date) days — consecutive dates share grp. GROUP BY user, grp HAVING COUNT(*) >= 3. (Gaps-and-islands trick.)' },
  { id: 'q-sql-13', category: 'SQL', sub: 'Patterns', prompt: 'Compute month-over-month revenue growth.', answer: 'CTE m: DATE_TRUNC(\'month\', order_date) AS month, SUM(amount) AS rev. Then SELECT month, rev, ROUND(100.0 * (rev − LAG(rev) OVER (ORDER BY month)) / LAG(rev) OVER (ORDER BY month), 2). Watch integer division and missing months.' },
  { id: 'q-sql-14', category: 'SQL', sub: 'Patterns', prompt: 'Top 3 products by revenue in each category.', answer: 'CTE with DENSE_RANK() (or ROW_NUMBER()) OVER (PARTITION BY category ORDER BY revenue DESC) AS r; WHERE r <= 3. Say which one you chose and how ties are handled — interviewers check that.' },
  { id: 'q-sql-15', category: 'SQL', sub: 'Window functions', prompt: '7-day moving average of daily signups.', answer: 'First build a complete date spine (generate_series LEFT JOIN counts, COALESCE 0). Then AVG(signups) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW). Without the spine, ROWS counts rows, not days.' },
  { id: 'q-sql-16', category: 'SQL', sub: 'Window functions', prompt: 'ROWS vs RANGE frames — and why LAST_VALUE often looks wrong.', answer: 'ROWS counts physical rows; RANGE includes all peers with the same ORDER BY value. With ORDER BY the default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, so LAST_VALUE returns the current row. Use ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING.' },
  { id: 'q-sql-17', category: 'SQL', sub: 'Patterns', prompt: 'Build a monthly cohort retention table.', answer: 'cohort_month = MIN(activity month) per user; for each activity compute months_since = month diff; COUNT(DISTINCT user) by cohort × months_since; divide by cohort size (months_since = 0). Pivot with conditional aggregation for the triangle.' },
  { id: 'q-sql-18', category: 'SQL', sub: 'Patterns', prompt: 'Funnel conversion (view → add_to_cart → purchase) from an events table.', answer: 'Per user: MAX(CASE WHEN event=\'view\' THEN 1 END) etc. (optionally enforce timestamp order). Then SUM each flag and divide step n by step n−1. Clarify: same session? time window? unique users vs events?' },
  { id: 'q-sql-19', category: 'SQL', sub: 'Patterns', prompt: 'Median without a MEDIAN function.', answer: 'PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY x) where supported. Otherwise ROW_NUMBER() OVER (ORDER BY x) AS rn and COUNT(*) OVER () AS n; AVG(x) WHERE rn IN ((n+1)/2, (n+2)/2) — handles odd and even n.' },
  { id: 'q-sql-20', category: 'SQL', sub: 'Joins', prompt: 'Employees who earn more than their managers.', answer: 'SELECT e.name FROM employee e JOIN employee m ON e.manager_id = m.id WHERE e.salary > m.salary. Self-join; use LEFT JOIN if you also need people without managers.' },
  { id: 'q-sql-21', category: 'SQL', sub: 'Performance', prompt: 'What is an index and when does it NOT help?', answer: 'A B-tree lets the engine seek instead of scanning. It doesn’t help with low-selectivity filters, functions on the column (non-sargable, e.g. YEAR(col)=2026), leading-wildcard LIKE \'%x\', tiny tables, or when the leftmost column of a composite index isn’t filtered. Indexes slow writes.' },
  { id: 'q-sql-22', category: 'SQL', sub: 'Performance', prompt: 'Clustered vs non-clustered vs covering index?', answer: 'Clustered: table rows stored in index order (one per table). Non-clustered: separate structure pointing to rows. Covering: index contains every column the query needs, so no table lookup is required (INCLUDE columns).' },
  { id: 'q-sql-23', category: 'SQL', sub: 'Window functions', prompt: 'Window functions vs GROUP BY?', answer: 'GROUP BY collapses rows to one per group. Window functions compute over a set of related rows but keep every row — e.g. each order alongside its customer’s total, rank or running sum.' },
  { id: 'q-sql-24', category: 'SQL', sub: 'Patterns', prompt: 'Pivot rows into columns without PIVOT.', answer: 'Conditional aggregation: SELECT key, SUM(CASE WHEN month = \'Jan\' THEN amount END) AS jan, SUM(CASE WHEN month = \'Feb\' THEN amount END) AS feb … GROUP BY key.' },
  { id: 'q-sql-25', category: 'SQL', sub: 'Concepts', prompt: 'DELETE vs TRUNCATE vs DROP?', answer: 'DELETE removes rows (optionally WHERE), logged per row, fires triggers, can roll back. TRUNCATE removes all rows quickly, resets identity, minimal logging. DROP removes the table definition itself.' },
  { id: 'q-sql-26', category: 'SQL', sub: 'Patterns', prompt: 'Find gaps in a sequence of ids or dates.', answer: 'SELECT id + 1 AS gap_start, next_id − 1 AS gap_end FROM (SELECT id, LEAD(id) OVER (ORDER BY id) AS next_id FROM t) s WHERE next_id − id > 1.' },
  { id: 'q-sql-27', category: 'SQL', sub: 'Concepts', prompt: 'Explain transaction isolation levels and their default in Postgres / MySQL.', answer: 'Read Uncommitted (dirty reads possible) → Read Committed (no dirty reads) → Repeatable Read (no non-repeatable reads) → Serializable (no phantoms; behaves as if serial). Postgres defaults to Read Committed; MySQL InnoDB to Repeatable Read.' },

  // ───────────────────────── DSA ─────────────────────────
  { id: 'q-dsa-01', category: 'DSA', sub: 'Basics', prompt: 'Array vs linked list — trade-offs?', answer: 'Array: O(1) index, cache-friendly, O(n) insert/delete in the middle, fixed or amortised resize. Linked list: O(1) insert/delete given the node, O(n) access, extra pointer memory, poor locality.' },
  { id: 'q-dsa-02', category: 'DSA', sub: 'Hashing', prompt: 'How does HashMap get O(1) average lookup? Worst case?', answer: 'hashCode → spread → bucket index; collisions chained in a list, converted to a red-black tree when a bucket exceeds 8 (Java 8+), so worst case O(log n) (O(n) before Java 8). Resizes at load factor 0.75 — amortised O(1).' },
  { id: 'q-dsa-03', category: 'DSA', sub: 'Patterns', prompt: 'Two pointers vs sliding window vs prefix sums — how do you pick?', answer: 'Two pointers: sorted input, pairs / partitioning. Sliding window: contiguous subarray/substring with a condition that is monotonic as the window grows. Prefix sum (+ hashmap): range sums, subarray-sum-equals-k, works with negatives where a window doesn’t.' },
  { id: 'q-dsa-04', category: 'DSA', sub: 'Arrays', prompt: 'Explain Kadane’s algorithm.', answer: 'cur = max(x, cur + x); best = max(best, cur). Either extend the current subarray or start fresh at x. O(n) time, O(1) space. Track start/end indices if asked for the subarray.' },
  { id: 'q-dsa-05', category: 'DSA', sub: 'Sorting', prompt: 'Merge sort vs quick sort.', answer: 'Merge: O(n log n) always, stable, O(n) extra space — good for linked lists / external sort. Quick: O(n log n) average, O(n²) worst with bad pivots, in-place, not stable, cache-friendly. Java: dual-pivot quicksort for primitives, TimSort for objects.' },
  { id: 'q-dsa-06', category: 'DSA', sub: 'Binary search', prompt: 'When can you binary search on the answer?', answer: 'When feasibility is monotonic over the answer space — if capacity X works, every X′ > X works. Binary search the smallest feasible value with an O(n) check. Koko eating bananas, ship packages within D days, split array largest sum.' },
  { id: 'q-dsa-07', category: 'DSA', sub: 'Linked list', prompt: 'Detect a cycle in a linked list and find where it starts.', answer: 'Floyd: slow moves 1, fast moves 2; if they meet there’s a cycle. Reset one pointer to head and move both by 1 — they meet at the cycle start. O(n) time, O(1) space.' },
  { id: 'q-dsa-08', category: 'DSA', sub: 'Linked list', prompt: 'Reverse a linked list iteratively — talk through it.', answer: 'prev = null, cur = head; while (cur != null) { next = cur.next; cur.next = prev; prev = cur; cur = next; } return prev. Recursive: reverse(head.next), then head.next.next = head; head.next = null.' },
  { id: 'q-dsa-09', category: 'DSA', sub: 'Graphs', prompt: 'BFS vs DFS — when do you use each?', answer: 'BFS (queue): shortest path in unweighted graphs, level order, nearest-X. DFS (stack / recursion): exhaustive search, connected components, cycle detection, topological sort, backtracking. Both O(V + E).' },
  { id: 'q-dsa-10', category: 'DSA', sub: 'Trees', prompt: 'How do you validate a BST?', answer: 'Recurse with (min, max) bounds: every node must satisfy min < val < max; left child gets (min, val), right gets (val, max). Comparing only with the parent is the classic bug. Alternative: inorder traversal must be strictly increasing.' },
  { id: 'q-dsa-11', category: 'DSA', sub: 'Heap', prompt: 'What is a heap? How do you solve top-K?', answer: 'Complete binary tree with the heap property; insert/poll O(log n), peek O(1). Top-K largest: keep a min-heap of size K, push each element, pop when size > K → O(n log K). Java: PriorityQueue (min-heap by default).' },
  { id: 'q-dsa-12', category: 'DSA', sub: 'Graphs', prompt: 'Topological sort — what and how?', answer: 'Ordering of a DAG’s vertices so every edge u→v has u before v. Kahn’s: compute indegrees, queue all zeros, pop, decrement neighbours, enqueue new zeros. If processed count < V there’s a cycle (Course Schedule).' },
  { id: 'q-dsa-13', category: 'DSA', sub: 'DP', prompt: 'Memoisation vs tabulation?', answer: 'Memoisation: top-down recursion + cache, computes only needed states, recursion-depth risk. Tabulation: bottom-up table in dependency order, no recursion, enables rolling-array space optimisation. Same asymptotic complexity.' },
  { id: 'q-dsa-14', category: 'DSA', sub: 'DP', prompt: 'How do you recognise a DP problem and set it up?', answer: 'Signals: count the ways / min / max / is it possible, with choices at each step, and overlapping subproblems. Define the state (what changes), the transition (choices), base cases, the answer cell. Write recursion first, then memoise.' },
  { id: 'q-dsa-15', category: 'DSA', sub: 'Greedy', prompt: 'Greedy vs DP — give a case where greedy fails.', answer: 'Greedy commits to the locally best choice and needs a proof (exchange argument). Coin change with {1, 3, 4} for 6: greedy picks 4+1+1 (3 coins), optimal is 3+3 (2 coins). DP explores all choices.' },
  { id: 'q-dsa-16', category: 'DSA', sub: 'Stack', prompt: 'What problems does a monotonic stack solve?', answer: 'Next greater / smaller element, daily temperatures, stock span, largest rectangle in histogram, trapping rain water. Each element is pushed and popped at most once → O(n).' },
  { id: 'q-dsa-17', category: 'DSA', sub: 'Stack', prompt: 'Implement a queue using two stacks — complexity?', answer: 'Push onto in-stack. On pop/peek, if out-stack is empty, move everything from in to out, then pop from out. Each element moves once → amortised O(1).' },
  { id: 'q-dsa-18', category: 'DSA', sub: 'Graphs', prompt: 'Dijkstra — idea and limitation.', answer: 'Greedy with a min-heap of tentative distances; pop the closest unvisited node and relax its edges. O((V + E) log V). Fails with negative edge weights — use Bellman-Ford.' },
  { id: 'q-dsa-19', category: 'DSA', sub: 'Backtracking', prompt: 'Backtracking template and complexities of subsets / permutations.', answer: 'choose → explore (recurse) → un-choose; prune invalid branches early. Subsets: 2ⁿ results, O(n·2ⁿ). Permutations: n!, O(n·n!). Combination sum: sort + skip duplicates.' },
  { id: 'q-dsa-20', category: 'DSA', sub: 'Java', prompt: 'String vs StringBuilder in a loop — why does it matter?', answer: 'String is immutable, so s += c in a loop copies every time → O(n²). StringBuilder appends into a growable buffer → amortised O(n).' },
  { id: 'q-dsa-21', category: 'DSA', sub: 'Basics', prompt: 'Explain amortised O(1) with ArrayList.add.', answer: 'When full, capacity grows (~1.5× in Java) and elements are copied — O(n) occasionally. Total copying across n adds is O(n), so each add is O(1) amortised.' },
  { id: 'q-dsa-22', category: 'DSA', sub: 'Basics', prompt: 'Give the complexity: nested loops, binary search, naive recursive Fibonacci, sorting.', answer: 'O(n²); O(log n); O(2ⁿ) naive (O(n) with memo); O(n log n) comparison sort lower bound.' },

  // ───────────────────────── Stats / ML / DL / Spark ─────────────────────────
  { id: 'q-st-01', category: 'Stats/ML', sub: 'Stats', prompt: 'Explain a p-value to a non-technical stakeholder.', answer: 'If there were truly no effect, the p-value is how often we’d see a result at least this extreme by chance. Small p → the data is surprising under "no effect". It is NOT the probability the null is true, and NOT the size or importance of the effect.' },
  { id: 'q-st-02', category: 'Stats/ML', sub: 'Stats', prompt: 'Type I vs Type II error — which is worse?', answer: 'Type I = false positive (rate α), Type II = false negative (rate β; power = 1 − β). Which is worse depends on cost: shipping a harmful feature (Type I) vs missing a cancer diagnosis (Type II).' },
  { id: 'q-st-03', category: 'Stats/ML', sub: 'Stats', prompt: 'What does the Central Limit Theorem actually say?', answer: 'For i.i.d. samples with finite variance, the distribution of the sample mean approaches normal as n grows — whatever the population’s shape. It justifies z/t intervals and tests on means. It does NOT say the data becomes normal.' },
  { id: 'q-st-04', category: 'Stats/ML', sub: 'Stats', prompt: 'Interpret a 95% confidence interval correctly.', answer: 'If we repeated the sampling many times, 95% of intervals built this way would contain the true parameter. It is not "a 95% probability the true value is in this specific interval" (that is a Bayesian credible interval).' },
  { id: 'q-st-05', category: 'Stats/ML', sub: 'Stats', prompt: 'z-test vs t-test vs chi-square vs ANOVA — when?', answer: 'z: proportions or known σ / large n. t: means with unknown σ — one-sample, two-sample (Welch), paired (before/after). Chi-square: categorical independence or goodness of fit. ANOVA: means across 3+ groups (then post-hoc tests).' },
  { id: 'q-st-06', category: 'Stats/ML', sub: 'Probability', prompt: 'Test: 99% sensitivity, 95% specificity, prevalence 1%. P(disease | positive)?', answer: '0.99×0.01 / (0.99×0.01 + 0.05×0.99) = 0.0099 / 0.0594 ≈ 16.7%. Base rates dominate — most positives are false positives when the condition is rare.' },
  { id: 'q-st-07', category: 'Stats/ML', sub: 'Stats', prompt: 'Correlation vs causation — how would you establish causation?', answer: 'Ice-cream sales and drownings correlate via summer (confounder). Causation: randomised experiment; otherwise quasi-experiments — difference-in-differences, regression discontinuity, instrumental variables, matching — while controlling for confounders.' },
  { id: 'q-st-08', category: 'Stats/ML', sub: 'Stats', prompt: 'What is Simpson’s paradox?', answer: 'A trend that holds within every group reverses when groups are combined, because group sizes differ and a confounder drives the mix. Classic: Berkeley admissions, kidney-stone treatments. Always segment before concluding.' },
  { id: 'q-st-09', category: 'Stats/ML', sub: 'Stats', prompt: 'When do you report median instead of mean?', answer: 'Skewed data or outliers — income, order value, session length, delivery time. Mean is pulled by the tail; median reflects the typical case. Report both + a percentile (p90) for operations metrics.' },
  { id: 'q-st-10', category: 'Stats/ML', sub: 'Probability', prompt: 'Binomial vs Poisson vs exponential?', answer: 'Binomial: # successes in n fixed trials with prob p. Poisson: # events in a fixed interval at rate λ (mean = variance = λ). Exponential: waiting time between Poisson events. Poisson ≈ Binomial when n large, p small.' },
  { id: 'q-st-11', category: 'Stats/ML', sub: 'Stats', prompt: 'What is statistical power and what increases it?', answer: 'P(reject H0 | effect is real) = 1 − β. Increase it with larger n, larger true effect, higher α, lower variance (better metrics, CUPED, stratification), one-sided tests where justified.' },
  { id: 'q-st-12', category: 'Stats/ML', sub: 'Stats', prompt: 'Selection bias vs survivorship bias — examples.', answer: 'Selection: the sample isn’t representative (surveying only app users about app satisfaction). Survivorship: only the "survivors" are observed (WWII bombers’ bullet holes; studying only successful startups).' },
  { id: 'q-ab-01', category: 'Stats/ML', sub: 'A/B testing', prompt: 'Design an A/B test for a new checkout button, end to end.', answer: 'Hypothesis → primary metric (checkout conversion) + guardrails (AOV, refunds, latency) → unit of randomisation (user) → sample size from baseline, MDE, α=0.05, power=0.8 → run ≥ 1–2 full weekly cycles → check sample-ratio mismatch → analyse (two-proportion z-test / CI) → segment sanity checks → decide and document.' },
  { id: 'q-ab-02', category: 'Stats/ML', sub: 'A/B testing', prompt: 'How do you compute sample size?', answer: 'n per arm ≈ 2(z₁₋α/₂ + z₁₋β)² σ² / δ². For proportions σ² = p(1 − p). Halving the MDE quadruples n. Use statsmodels / Evan Miller’s calculator and state your assumptions.' },
  { id: 'q-ab-03', category: 'Stats/ML', sub: 'A/B testing', prompt: 'What is the peeking problem?', answer: 'Checking results repeatedly and stopping at the first significant p-value inflates the false-positive rate far above α. Fix: pre-registered fixed horizon, sequential testing with alpha spending, or Bayesian methods.' },
  { id: 'q-ab-04', category: 'Stats/ML', sub: 'A/B testing', prompt: 'Novelty and primacy effects?', answer: 'Users react to change itself — novelty inflates early engagement, primacy (change aversion) depresses it. Run long enough, plot the effect over time, analyse new users separately.' },
  { id: 'q-ab-05', category: 'Stats/ML', sub: 'A/B testing', prompt: 'Conversion is up 2% but revenue per user is down. What now?', answer: 'Check data quality and SRM first. Then decompose revenue = conversion × AOV; segment by user type / category; look at guardrails. The decision depends on the primary metric agreed before launch — probably don’t ship until the revenue drop is understood.' },
  { id: 'q-ab-06', category: 'Stats/ML', sub: 'A/B testing', prompt: 'Why does multiple testing matter, and how do you correct for it?', answer: '20 independent metrics at α = 0.05 → ~64% chance of at least one false positive. Bonferroni (α/m, conservative) controls family-wise error; Benjamini-Hochberg controls false discovery rate. Better: one pre-declared primary metric.' },
  { id: 'q-ab-07', category: 'Stats/ML', sub: 'A/B testing', prompt: 'What if you can’t randomise?', answer: 'Quasi-experiments: difference-in-differences (parallel trends), synthetic control, regression discontinuity, instrumental variables, propensity-score matching. State the assumption each one relies on.' },
  { id: 'q-ml-01', category: 'Stats/ML', sub: 'ML', prompt: 'Explain the bias-variance trade-off.', answer: 'Expected error = bias² + variance + irreducible noise. Simple models underfit (high bias); flexible models overfit (high variance). Manage with regularisation, more data, ensembling, model selection via CV.' },
  { id: 'q-ml-02', category: 'Stats/ML', sub: 'ML', prompt: 'How do you detect and fix overfitting?', answer: 'Train ≫ validation performance; learning curves diverge. Fix: more data, regularisation (L1/L2, dropout), simpler model, early stopping, feature selection, augmentation, proper CV.' },
  { id: 'q-ml-03', category: 'Stats/ML', sub: 'ML', prompt: 'Precision vs recall — when do you optimise each?', answer: 'Precision = TP/(TP+FP): cost of false alarms (spam filter, recommending stocks). Recall = TP/(TP+FN): cost of misses (fraud, cancer screening). F1 balances; pick the threshold from the business cost of FP vs FN.' },
  { id: 'q-ml-04', category: 'Stats/ML', sub: 'ML', prompt: 'Why can accuracy be misleading? (Use your Outright story.)', answer: 'With heavy class imbalance, predicting the majority class gets high accuracy and zero recall on the class you care about. Tell the story: what the accuracy was, what recall/precision really were, the metric you switched to (PR-AUC / recall / F1), and what changed.' },
  { id: 'q-ml-05', category: 'Stats/ML', sub: 'ML', prompt: 'ROC-AUC vs PR-AUC?', answer: 'ROC uses FPR = FP/(FP+TN); with many negatives FPR stays tiny, so ROC-AUC looks great. PR-AUC focuses on the positive class (precision vs recall) — the honest metric under heavy imbalance. Baseline PR-AUC = positive rate.' },
  { id: 'q-ml-06', category: 'Stats/ML', sub: 'ML', prompt: 'How do you handle class imbalance?', answer: 'Right metrics first (PR-AUC, recall@precision). Then class weights, resampling (under/over-sampling, SMOTE — on the training fold only), threshold tuning, anomaly-detection framing, collecting more minority data.' },
  { id: 'q-ml-07', category: 'Stats/ML', sub: 'ML', prompt: 'L1 vs L2 regularisation?', answer: 'L1 (Lasso) adds λΣ|w|: diamond-shaped constraint → corners → exact zeros → feature selection. L2 (Ridge) adds λΣw²: shrinks smoothly, stabilises under multicollinearity. ElasticNet mixes both.' },
  { id: 'q-ml-08', category: 'Stats/ML', sub: 'ML', prompt: 'Assumptions of linear regression?', answer: 'Linearity, independent errors, homoscedasticity (constant variance), normally distributed residuals (for inference), no perfect multicollinearity. Check with residual plots, Q-Q plot, VIF, Durbin-Watson.' },
  { id: 'q-ml-09', category: 'Stats/ML', sub: 'ML', prompt: 'Interpret a logistic regression coefficient.', answer: 'It models log-odds linearly: log(p/(1−p)) = β₀ + βx. A one-unit increase in x multiplies the odds by e^β (holding others fixed). Trained with log-loss, not MSE (MSE + sigmoid is non-convex).' },
  { id: 'q-ml-10', category: 'Stats/ML', sub: 'ML', prompt: 'Bagging vs boosting?', answer: 'Bagging: independent models on bootstrap samples, averaged → reduces variance (Random Forest). Boosting: sequential models, each fitting the previous errors → reduces bias (AdaBoost, GBM, XGBoost); more sensitive to noise, needs learning-rate / depth tuning.' },
  { id: 'q-ml-11', category: 'Stats/ML', sub: 'ML', prompt: 'Why is a Random Forest better than one decision tree?', answer: 'Each tree sees a bootstrap sample and a random feature subset per split, so trees are decorrelated; averaging them cuts variance without much added bias. Bonus: OOB error as free validation, feature importances.' },
  { id: 'q-ml-12', category: 'Stats/ML', sub: 'ML', prompt: 'What makes XGBoost / LightGBM fast and accurate?', answer: 'Gradient boosting with second-order gradients, explicit regularisation on leaves, shrinkage, row/column subsampling, histogram-based split finding, sparsity-aware handling of missing values. LightGBM adds leaf-wise growth, GOSS and feature bundling.' },
  { id: 'q-ml-13', category: 'Stats/ML', sub: 'ML', prompt: 'Gini impurity vs entropy?', answer: 'Gini = 1 − Σp², entropy = −Σp log₂p. Both measure node impurity; information gain = parent impurity − weighted child impurity. Results are usually similar; Gini is slightly cheaper (no log).' },
  { id: 'q-ml-14', category: 'Stats/ML', sub: 'ML', prompt: 'k-means: algorithm, assumptions, choosing k.', answer: 'Init (k-means++), assign points to the nearest centroid, recompute centroids, repeat until stable. Assumes roughly spherical, similar-size clusters; scale-sensitive (standardise). Choose k with elbow / silhouette + business sense. DBSCAN for arbitrary shapes / noise.' },
  { id: 'q-ml-15', category: 'Stats/ML', sub: 'ML', prompt: 'Explain PCA.', answer: 'Standardise, compute the covariance matrix, take its eigenvectors (principal components) ordered by eigenvalue (variance explained), project onto the top k. Components are orthogonal linear combinations; choose k by cumulative explained variance.' },
  { id: 'q-ml-16', category: 'Stats/ML', sub: 'ML', prompt: 'What is data leakage? Give examples.', answer: 'Information unavailable at prediction time leaks into training: fitting scalers/encoders on all data before splitting, target-derived features, future data in time series, the same patient in train and test, duplicates across splits.' },
  { id: 'q-ml-17', category: 'Stats/ML', sub: 'ML', prompt: 'How would you encode a high-cardinality categorical?', answer: 'Target / mean encoding with out-of-fold computation + smoothing, frequency encoding, hashing trick, learned embeddings, or native categorical support (LightGBM / CatBoost). One-hot explodes dimensionality.' },
  { id: 'q-ml-18', category: 'Stats/ML', sub: 'ML', prompt: 'How do you monitor a model in production?', answer: 'Input drift (PSI, KS test), prediction drift, performance once labels arrive, data-quality checks, latency / error rates. Alert thresholds trigger investigation and retraining; keep a shadow / champion-challenger setup.' },
  { id: 'q-ml-19', category: 'Stats/ML', sub: 'ML', prompt: 'What is the kernel trick in SVMs?', answer: 'SVMs only need dot products; a kernel K(x, y) computes the dot product in a high-dimensional feature space without mapping explicitly — enabling non-linear boundaries (RBF, polynomial). C controls the soft-margin trade-off.' },
  { id: 'q-ml-20', category: 'Stats/ML', sub: 'ML', prompt: 'What is SHAP?', answer: 'Shapley values from cooperative game theory: each feature’s average marginal contribution to a prediction relative to a baseline. Additive, locally accurate, consistent; TreeSHAP is fast for tree ensembles. Gives local explanations and global importance.' },
  { id: 'q-ml-21', category: 'Stats/ML', sub: 'ML', prompt: 'Why stratified k-fold? Why not random k-fold for time series?', answer: 'Stratified keeps class ratios equal in every fold — essential under imbalance. Time series needs forward-chaining (train on past, validate on future); random folds leak the future.' },
  { id: 'q-dl-01', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'Why do neural networks need non-linear activations?', answer: 'Without them, stacked linear layers collapse into one linear map — no matter the depth, the network can only learn linear functions.' },
  { id: 'q-dl-02', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'Vanishing gradients — cause and fixes.', answer: 'Backprop multiplies many derivatives < 1 (sigmoid/tanh saturate), so early layers barely learn. Fixes: ReLU-family activations, residual connections, batch/layer norm, He/Xavier init, LSTM/GRU gates for sequences.' },
  { id: 'q-dl-03', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'Explain self-attention.', answer: 'Each token is projected to Query, Key, Value. Attention weights = softmax(QKᵀ / √dₖ); output = weights × V. Every token can attend to every other token in one step; multi-head attention learns several relation types in parallel. Positional encodings add order.' },
  { id: 'q-dl-04', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'BERT vs GPT?', answer: 'BERT: encoder-only, bidirectional, masked-language-model pretraining → classification, NER, embeddings. GPT: decoder-only, causal (left-to-right) next-token pretraining → generation. T5/BART are encoder-decoder.' },
  { id: 'q-dl-05', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'Transfer learning vs fine-tuning (NeuroLens).', answer: 'Feature extraction: freeze the pretrained backbone, train a new head. Fine-tuning: unfreeze some or all layers and train with a low learning rate. With small medical datasets, start frozen, then unfreeze top blocks; use augmentation and watch for leakage.' },
  { id: 'q-dl-06', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'What is RAG and why use it instead of fine-tuning?', answer: 'Retrieve relevant chunks from a knowledge base and put them in the prompt. Gives fresh / private knowledge, citations and cheap updates. Fine-tuning changes behaviour and style; it’s an unreliable way to inject facts.' },
  { id: 'q-dl-07', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'How do you choose a chunking strategy?', answer: 'Respect semantic boundaries (headings, paragraphs), balance size (too small loses context, too big dilutes relevance — often 300–800 tokens), add overlap, attach metadata. Decide empirically with retrieval hit-rate on an eval set.' },
  { id: 'q-dl-08', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'How do you evaluate a RAG system?', answer: 'Retrieval: recall@k / hit-rate, MRR on a labelled question set. Generation: faithfulness (grounded in retrieved context), answer relevance, citation accuracy. LLM-as-judge calibrated against human labels; track latency and cost.' },
  { id: 'q-dl-09', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'LLM-as-judge — what is it and what are the pitfalls?', answer: 'An LLM grades outputs against a rubric. Pitfalls: position and verbosity bias, self-preference, inconsistency, cost and latency. Mitigate with clear rubrics, calibration on labelled data, and deterministic checks first — exactly why KYRO is rule-dominant with the LLM as the last tier.' },
  { id: 'q-dl-10', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'Temperature vs top-p?', answer: 'Temperature rescales logits before softmax (low → near-greedy, high → diverse). Top-p (nucleus) samples only from the smallest token set whose cumulative probability ≥ p. Usually tune one, not both.' },
  { id: 'q-dl-11', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'What is LoRA?', answer: 'Freeze the base weights W and learn a low-rank update ΔW = A·B (rank r ≪ d) on selected layers — orders of magnitude fewer trainable parameters. QLoRA quantises the frozen base to 4-bit to fit on small GPUs.' },
  { id: 'q-dl-12', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'How do LLM agents use tools?', answer: 'The model emits a structured call (tool name + JSON args); the runtime executes it and returns the result into context; loop until done. Orchestration frameworks (LangGraph) add explicit state, branches, retries, human-in-the-loop and guardrails.' },
  { id: 'q-dl-13', category: 'Stats/ML', sub: 'DL & GenAI', prompt: 'What does batch normalisation do?', answer: 'Normalises a layer’s inputs over the mini-batch, then applies a learned scale and shift. Stabilises and speeds up training, allows higher learning rates, mild regularisation. Uses running stats at inference.' },
  { id: 'q-sp-01', category: 'Stats/ML', sub: 'Spark', prompt: 'Explain Spark’s architecture.', answer: 'Driver builds a logical plan → DAG; cluster manager allocates executors; an action triggers a job, split into stages at shuffle boundaries, each stage into tasks (one per partition). Transformations are lazy until an action.' },
  { id: 'q-sp-02', category: 'Stats/ML', sub: 'Spark', prompt: 'repartition vs coalesce?', answer: 'repartition(n) does a full shuffle — can increase or decrease and balances partitions. coalesce(n) merges partitions without a full shuffle — only decreases, may be uneven. Use coalesce before writing fewer files.' },
  { id: 'q-sp-03', category: 'Stats/ML', sub: 'Spark', prompt: 'What is a broadcast join and when do you use it?', answer: 'Ship the small table to every executor so the large table doesn’t shuffle. Use when one side fits in memory (auto below spark.sql.autoBroadcastJoinThreshold, default 10 MB) or via broadcast() hint.' },
  { id: 'q-sp-04', category: 'Stats/ML', sub: 'Spark', prompt: 'Why avoid Python UDFs in PySpark?', answer: 'Rows are serialised between the JVM and Python workers and the UDF is a black box to the Catalyst optimiser. Prefer built-in functions; if needed, use pandas UDFs (Arrow-vectorised).' },
  { id: 'q-sp-05', category: 'Stats/ML', sub: 'Spark', prompt: 'What is data skew and how do you handle it?', answer: 'A few keys hold most of the data → a few straggler tasks. Fixes: AQE skew-join handling, salting hot keys, broadcasting the small side, processing hot keys separately, pre-aggregation.' },
  { id: 'q-sp-06', category: 'Stats/ML', sub: 'Spark', prompt: 'What does Delta Lake add on top of Parquet?', answer: 'A transaction log: ACID writes, time travel / versioning, schema enforcement and evolution, MERGE upserts and deletes, OPTIMIZE / Z-ordering for file compaction and data skipping.' },
  { id: 'q-sp-07', category: 'Stats/ML', sub: 'Spark', prompt: 'Narrow vs wide transformations?', answer: 'Narrow (map, filter, withColumn): each output partition depends on one input partition — no shuffle. Wide (groupBy, join, distinct, orderBy): data moves across partitions — shuffle, new stage, expensive.' },

  // ───────────────────────── Core CS ─────────────────────────
  { id: 'q-db-01', category: 'Core CS', sub: 'DBMS', prompt: 'Explain 1NF, 2NF, 3NF and BCNF.', answer: '1NF: atomic values, no repeating groups. 2NF: 1NF + no partial dependency of a non-key attribute on part of a composite key. 3NF: 2NF + no transitive dependency (non-key → non-key). BCNF: every determinant is a candidate key.' },
  { id: 'q-db-02', category: 'Core CS', sub: 'DBMS', prompt: 'Super key vs candidate key vs primary key vs foreign key.', answer: 'Super key: any set that uniquely identifies a row. Candidate key: a minimal super key. Primary key: the chosen candidate key (unique, not null). Foreign key: references another table’s key, enforcing referential integrity.' },
  { id: 'q-db-03', category: 'Core CS', sub: 'DBMS', prompt: 'Explain ACID with a bank-transfer example.', answer: 'Atomicity: debit and credit both happen or neither (undo log). Consistency: constraints hold before and after. Isolation: concurrent transfers don’t see partial states (locks / MVCC). Durability: once committed, it survives crashes (WAL).' },
  { id: 'q-db-04', category: 'Core CS', sub: 'DBMS', prompt: 'Dirty read, non-repeatable read, phantom read?', answer: 'Dirty: reading uncommitted data. Non-repeatable: re-reading a row gives a different value because another txn committed an update. Phantom: re-running a range query returns new rows because another txn inserted.' },
  { id: 'q-db-05', category: 'Core CS', sub: 'DBMS', prompt: 'B-tree vs B+ tree — why do databases use B+ trees?', answer: 'In a B+ tree all records live in the leaves and leaves are linked — fast range scans; internal nodes hold only keys → higher fan-out → shallower tree → fewer disk reads.' },
  { id: 'q-db-06', category: 'Core CS', sub: 'DBMS', prompt: 'What is two-phase locking?', answer: 'Growing phase acquires locks, shrinking phase releases; no lock acquired after the first release. Guarantees conflict serialisability. Strict 2PL holds exclusive locks until commit — avoids cascading aborts. Can still deadlock.' },
  { id: 'q-db-07', category: 'Core CS', sub: 'DBMS', prompt: 'SQL vs NoSQL — how do you choose?', answer: 'SQL: structured relations, joins, strong consistency, complex queries, transactions. NoSQL: flexible schema, horizontal scale, specific access patterns (document, key-value, wide-column, graph). Choose by data shape, access patterns, consistency and scale needs.' },
  { id: 'q-db-08', category: 'Core CS', sub: 'DBMS', prompt: 'Explain the CAP theorem.', answer: 'Under a network partition a distributed store must choose Consistency (every read sees the latest write) or Availability (every request gets a response). CP vs AP systems. PACELC adds: else (no partition), trade latency vs consistency.' },
  { id: 'q-db-09', category: 'Core CS', sub: 'DBMS', prompt: 'When would you denormalise?', answer: 'Read-heavy and analytical workloads where joins dominate cost — data warehouses (star schema), caches, reporting tables. Trade-off: redundancy and update anomalies, so keep a source of truth.' },
  { id: 'q-db-10', category: 'Core CS', sub: 'DBMS', prompt: 'MongoDB: embed or reference? (Explain with Confer.)', answer: 'Embed when data is read together, one-to-few and bounded (16 MB doc limit) — e.g. a booking’s slot details. Reference when one-to-many is unbounded or entities are shared — users, experts, payments. Index fields you query on.' },
  { id: 'q-db-11', category: 'Core CS', sub: 'DBMS', prompt: 'View vs materialised view?', answer: 'A view is a stored query, computed on every read. A materialised view stores the result and must be refreshed — faster reads, possibly stale data.' },
  { id: 'q-db-12', category: 'Core CS', sub: 'DBMS', prompt: 'Star schema vs snowflake schema?', answer: 'Star: central fact table with denormalised dimension tables — simple, fast joins. Snowflake: dimensions normalised into sub-dimensions — less redundancy, more joins.' },
  { id: 'q-os-01', category: 'Core CS', sub: 'OS', prompt: 'Process vs thread?', answer: 'Process: independent address space, own resources, heavier creation and context switch, isolated. Thread: lightweight unit within a process sharing memory and files; own stack and registers; cheaper but needs synchronisation.' },
  { id: 'q-os-02', category: 'Core CS', sub: 'OS', prompt: 'What happens during a context switch?', answer: 'Save the running process’s CPU state (registers, PC, stack pointer) into its PCB, update scheduling queues, load the next process’s state, switch address space (TLB flush for processes). Pure overhead.' },
  { id: 'q-os-03', category: 'Core CS', sub: 'OS', prompt: 'Which scheduling algorithm minimises average waiting time? Trade-offs?', answer: 'SJF (non-preemptive) / SRTF (preemptive) are optimal for average waiting time but need burst estimates and can starve long jobs (fix: aging). RR gives responsiveness (quantum trade-off); FCFS suffers convoy effect; MLFQ adapts.' },
  { id: 'q-os-04', category: 'Core CS', sub: 'OS', prompt: 'Mutex vs semaphore?', answer: 'Mutex: a lock with ownership — only the holder unlocks; mutual exclusion. Semaphore: an integer counter with wait/signal and no ownership; counting semaphores manage pools of N resources and signalling between threads.' },
  { id: 'q-os-05', category: 'Core CS', sub: 'OS', prompt: 'Deadlock conditions and handling strategies.', answer: 'Coffman: mutual exclusion, hold and wait, no preemption, circular wait — all four needed. Prevent by breaking one (e.g. global lock ordering), avoid (Banker’s), detect + recover (wait-for graph, kill/rollback), or ignore (ostrich).' },
  { id: 'q-os-06', category: 'Core CS', sub: 'OS', prompt: 'Banker’s algorithm in one minute.', answer: 'Before granting a request, pretend to allocate and check for a safe state: find a sequence in which every process’s remaining need (Max − Allocation) can be met from Available plus resources released by earlier processes. Grant only if safe.' },
  { id: 'q-os-07', category: 'Core CS', sub: 'OS', prompt: 'Paging vs segmentation?', answer: 'Paging: fixed-size pages/frames, no external fragmentation, some internal; invisible to the programmer. Segmentation: variable-size logical segments (code, stack, heap), external fragmentation. Many systems combine them.' },
  { id: 'q-os-08', category: 'Core CS', sub: 'OS', prompt: 'What is virtual memory? What is thrashing?', answer: 'Each process gets a large logical address space backed by RAM + disk; pages load on demand via page faults. Thrashing: working sets don’t fit, so the system spends most time paging. Fix: fewer processes, more RAM, working-set model.' },
  { id: 'q-os-09', category: 'Core CS', sub: 'OS', prompt: 'FIFO vs LRU vs Optimal page replacement; Belady’s anomaly.', answer: 'Optimal evicts the page used farthest in future (benchmark only). LRU evicts least recently used (good approximation). FIFO evicts the oldest — and can suffer Belady’s anomaly: more frames → more faults.' },
  { id: 'q-os-10', category: 'Core CS', sub: 'OS', prompt: 'What is a race condition and how do you prevent it?', answer: 'Outcome depends on the interleaving of threads accessing shared data (e.g. count++ is read-modify-write). Prevent with mutual exclusion (locks, synchronized), atomic operations, immutable data, or confinement.' },
  { id: 'q-os-11', category: 'Core CS', sub: 'OS', prompt: 'User mode vs kernel mode; what is a system call?', answer: 'Kernel mode can execute privileged instructions and access hardware; user mode can’t. A system call is a controlled trap from user to kernel mode to request a service (read, write, fork) and return.' },
  { id: 'q-os-12', category: 'Core CS', sub: 'OS', prompt: 'Internal vs external fragmentation?', answer: 'Internal: wasted space inside an allocated block (fixed-size pages/partitions). External: enough total free memory but not contiguous (variable partitions, segmentation). Compaction or paging addresses external.' },
  { id: 'q-cn-01', category: 'Core CS', sub: 'Networks', prompt: 'What happens when you type a URL and press Enter?', answer: 'Parse URL → browser/OS cache → DNS resolution (recursive resolver → root → TLD → authoritative) → TCP handshake → TLS handshake → HTTP request → server/load balancer/app → response → HTML parse, fetch sub-resources, render. Mention caching and CDNs.' },
  { id: 'q-cn-02', category: 'Core CS', sub: 'Networks', prompt: 'TCP vs UDP?', answer: 'TCP: connection-oriented, reliable, ordered, flow + congestion control, heavier (web, email, DB). UDP: connectionless, no guarantees, low overhead and latency (DNS, video calls, gaming, QUIC builds on it).' },
  { id: 'q-cn-03', category: 'Core CS', sub: 'Networks', prompt: 'Explain the TCP three-way handshake and teardown.', answer: 'SYN (client seq x) → SYN-ACK (server seq y, ack x+1) → ACK (ack y+1). Teardown: FIN → ACK, FIN → ACK (four steps); the closer waits in TIME_WAIT for 2×MSL to absorb stray packets.' },
  { id: 'q-cn-04', category: 'Core CS', sub: 'Networks', prompt: 'OSI layers with an example protocol each.', answer: 'Physical (cables, signals) · Data link (Ethernet, MAC, switches) · Network (IP, routers) · Transport (TCP/UDP) · Session (session mgmt) · Presentation (TLS, encoding) · Application (HTTP, DNS, SMTP).' },
  { id: 'q-cn-05', category: 'Core CS', sub: 'Networks', prompt: 'How does DNS resolution work?', answer: 'Check browser/OS cache → recursive resolver → root server (points to TLD) → TLD server (.com) → authoritative server returns the A/AAAA record. Resolver caches by TTL. Record types: A, AAAA, CNAME, MX, NS, TXT.' },
  { id: 'q-cn-06', category: 'Core CS', sub: 'Networks', prompt: 'How does HTTPS / TLS work?', answer: 'Client hello (ciphers) → server sends certificate signed by a CA → client verifies chain → key exchange (ECDHE) establishes a shared secret → symmetric encryption for the session. Asymmetric for authentication + key exchange, symmetric for speed.' },
  { id: 'q-cn-07', category: 'Core CS', sub: 'Networks', prompt: 'HTTP methods and idempotency; PUT vs PATCH vs POST.', answer: 'GET, PUT, DELETE are idempotent; POST is not. PUT replaces the whole resource at a known URI; PATCH partially updates; POST creates a subordinate resource / triggers processing. Payments use idempotency keys to make POST safe to retry.' },
  { id: 'q-cn-08', category: 'Core CS', sub: 'Networks', prompt: 'Common HTTP status codes — 401 vs 403?', answer: '200 OK, 201 Created, 204 No Content, 301/302 redirects, 304 Not Modified, 400 Bad Request, 401 Unauthenticated (who are you?), 403 Forbidden (I know you, not allowed), 404, 409 Conflict, 429 Too Many Requests, 500, 502 Bad Gateway, 503 Unavailable.' },
  { id: 'q-cn-09', category: 'Core CS', sub: 'Networks', prompt: 'Flow control vs congestion control?', answer: 'Flow control protects the receiver — sliding window sized by receiver’s advertised window. Congestion control protects the network — slow start, congestion avoidance (AIMD), fast retransmit / recovery.' },
  { id: 'q-cn-10', category: 'Core CS', sub: 'Networks', prompt: 'How many usable hosts in a /26? What is CIDR?', answer: '32 − 26 = 6 host bits → 2⁶ − 2 = 62 usable hosts (network + broadcast reserved); mask 255.255.255.192. CIDR replaces fixed classes with variable-length prefixes for efficient allocation and route aggregation.' },
  { id: 'q-cn-11', category: 'Core CS', sub: 'Networks', prompt: 'What is NAT and why is it used?', answer: 'Network Address Translation maps private IPs (10/8, 172.16/12, 192.168/16) to a public IP (with ports, PAT). Conserves IPv4 addresses and hides internal topology; complicates peer-to-peer.' },
  { id: 'q-cn-12', category: 'Core CS', sub: 'Networks', prompt: 'HTTP/1.1 vs HTTP/2 vs HTTP/3 — and where do WebSockets fit?', answer: '1.1: text, one request at a time per connection (head-of-line blocking). 2: binary framing, multiplexed streams, header compression over one TCP connection. 3: over QUIC (UDP) — no TCP head-of-line blocking. WebSockets upgrade an HTTP connection to full-duplex messaging (KYRO’s live feed).' },
  { id: 'q-oop-01', category: 'Core CS', sub: 'OOP / Java', prompt: 'The four pillars of OOP with examples.', answer: 'Encapsulation (private fields + methods guarding invariants — Account.withdraw). Abstraction (expose what, hide how — interface PaymentGateway). Inheritance (SavingsAccount extends Account). Polymorphism (Account a = new SavingsAccount(); a.interest() dispatches at runtime).' },
  { id: 'q-oop-02', category: 'Core CS', sub: 'OOP / Java', prompt: 'Overloading vs overriding?', answer: 'Overloading: same name, different parameter lists, resolved at compile time. Overriding: subclass redefines an inherited method with the same signature, resolved at runtime; can’t reduce visibility or throw broader checked exceptions; @Override.' },
  { id: 'q-oop-03', category: 'Core CS', sub: 'OOP / Java', prompt: 'Abstract class vs interface (Java 8+).', answer: 'Abstract class: state (fields), constructors, partial implementation, single inheritance — "is-a" with shared code. Interface: contract, multiple inheritance of type, default/static methods, no instance state — "can-do" capability.' },
  { id: 'q-oop-04', category: 'Core CS', sub: 'OOP / Java', prompt: 'Why no multiple inheritance of classes in Java?', answer: 'The diamond problem: two parents with the same method → ambiguity. Java allows multiple interfaces; if two default methods clash, the class must override and can call A.super.method() explicitly.' },
  { id: 'q-oop-05', category: 'Core CS', sub: 'OOP / Java', prompt: 'The equals / hashCode contract.', answer: 'If a.equals(b) then a.hashCode() == b.hashCode() (not vice versa). Override both together, using the same fields; otherwise HashMap/HashSet break (equal objects land in different buckets). equals must be reflexive, symmetric, transitive, consistent.' },
  { id: 'q-oop-06', category: 'Core CS', sub: 'OOP / Java', prompt: 'Why is String immutable in Java?', answer: 'String pool sharing, security (class names, URLs, credentials can’t be altered after checks), thread safety for free, cached hashCode (great as HashMap keys).' },
  { id: 'q-oop-07', category: 'Core CS', sub: 'OOP / Java', prompt: 'final vs finally vs finalize?', answer: 'final: constant variable / non-overridable method / non-extendable class. finally: block that always runs after try/catch (cleanup). finalize: deprecated GC hook — use try-with-resources / Cleaner instead.' },
  { id: 'q-oop-08', category: 'Core CS', sub: 'OOP / Java', prompt: 'Checked vs unchecked exceptions?', answer: 'Checked (IOException, SQLException) must be declared or caught — recoverable conditions. Unchecked (RuntimeException: NPE, IllegalArgument) signal programming errors. Errors (OutOfMemoryError) shouldn’t be caught.' },
  { id: 'q-oop-09', category: 'Core CS', sub: 'OOP / Java', prompt: 'ArrayList vs LinkedList; HashMap vs TreeMap vs LinkedHashMap.', answer: 'ArrayList: O(1) random access, amortised O(1) append — default choice. LinkedList: O(1) insert at ends, O(n) access. HashMap: O(1) avg, no order. TreeMap: sorted, O(log n). LinkedHashMap: insertion/access order — LRU caches.' },
  { id: 'q-oop-10', category: 'Core CS', sub: 'OOP / Java', prompt: 'Explain SOLID.', answer: 'Single responsibility · Open/closed (extend without modifying) · Liskov substitution (subtypes usable as base types) · Interface segregation (small, specific interfaces) · Dependency inversion (depend on abstractions, inject dependencies).' },
  { id: 'q-oop-11', category: 'Core CS', sub: 'OOP / Java', prompt: 'Write a thread-safe Singleton.', answer: 'Simplest: enum Singleton { INSTANCE; }. Or the holder idiom: private static class Holder { static final S I = new S(); } — lazy and thread-safe via class loading. Double-checked locking needs a volatile field.' },
  { id: 'q-oop-12', category: 'Core CS', sub: 'OOP / Java', prompt: 'Composition vs inheritance — when to prefer composition?', answer: 'Inheritance couples you to the parent’s implementation (fragile base class). Prefer composition ("has-a") when you need behaviour reuse or swappable strategies — e.g. a Notifier holding a Channel (Email/SMS) instead of EmailNotifier extends Notifier.' },
  { id: 'q-oop-13', category: 'Core CS', sub: 'OOP / Java', prompt: 'What does static mean on a field, method, block and nested class?', answer: 'Belongs to the class, not instances: one shared field; method callable without an object (no this); static block runs once at class load; static nested class doesn’t hold a reference to an outer instance.' },

  // ───────────────────────── Case / Guesstimate ─────────────────────────
  { id: 'q-gs-01', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'Estimate the number of private cars in Bengaluru.', answer: 'Structure: population (~13–14M) → households (~3.5M at ~4/household) → car ownership by income segment (e.g. high 70%, middle 30%, low 2%) → ~0.9–1.2M + company/fleet cars. Sanity-check against vehicle registration scale. State assumptions out loud.' },
  { id: 'q-gs-02', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'Estimate daily food-delivery orders on Swiggy in India.', answer: 'Urban internet users in top cities → % who order online → orders per month per user by segment → divide by 30 → Swiggy market share. Cross-check with average orders per delivery partner per day × partners.' },
  { id: 'q-gs-03', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'How many smartphones are sold in India per year?', answer: 'Smartphone users (~650–750M) ÷ replacement cycle (~2.5–3 years) + first-time buyers. Segment by price band if asked for market value. Sanity check vs ~150M/year scale.' },
  { id: 'q-gs-04', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'How many cups of chai are sold in Kolkata per day?', answer: 'Supply side: tea stalls per km² or per 1,000 people × cups per stall per day. Demand side: population × % who drink outside × cups/day. Do both, reconcile.' },
  { id: 'q-gs-05', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'Daily revenue of a Starbucks outlet in a Bengaluru mall.', answer: 'Operating hours × peak/off-peak customers per hour (counter throughput ~1 order/min at peak) × average ticket (~₹350–450). Adjust weekday vs weekend.' },
  { id: 'q-gs-06', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'Estimate the number of UPI transactions per day in India.', answer: 'Active UPI users × transactions per user per day by segment (merchant payments, P2P, bills). Compare the result with the published NPCI order of magnitude (hundreds of millions per day).' },
  { id: 'q-gs-07', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'How many petrol pumps are there in Mumbai?', answer: 'Vehicles in Mumbai × % refuelling per day × average fills per vehicle → daily fills; ÷ fills a pump can serve per day (nozzles × hours × fills/hour × utilisation).' },
  { id: 'q-gs-08', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'Annual revenue of one multiplex screen.', answer: 'Shows/day × seats × occupancy (weekday vs weekend) × average ticket price × 365 + F&B per head (often 30–40% of revenue) + ads.' },
  { id: 'q-gs-09', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'How many laptops are sold in India per year?', answer: 'Segments: students, working professionals, enterprises, government schemes. Each: population × penetration ÷ replacement cycle. Sum, sanity-check.' },
  { id: 'q-gs-10', category: 'Case/Guesstimate', sub: 'Guesstimate', prompt: 'How many passengers depart from Delhi airport per day?', answer: 'Runways × movements/hour × operating hours → flights/day; ÷2 for departures × average seats × load factor (~80–85%).' },
  { id: 'q-cs-01', category: 'Case/Guesstimate', sub: 'Diagnostic', prompt: 'Swiggy orders dropped 20% week-over-week. How do you investigate?', answer: '1) Is it real? tracking, definitions, pipelines. 2) Is it sudden or gradual, all cities or some? 3) Segment: city, platform, app version, new vs returning, cuisine, time of day. 4) Funnel: app opens → menu → cart → payment → delivered — where’s the drop? 5) Internal: release, pricing / fees, restaurant supply, outage. External: competitor offer, weather, festival, regulation. 6) Hypothesis → verify → fix.' },
  { id: 'q-cs-02', category: 'Case/Guesstimate', sub: 'Case', prompt: 'A retailer’s profits are declining. Walk me through it.', answer: 'Profit = revenue − cost. Revenue = price × volume, split by product/channel/region; costs = fixed + variable. Compare over time and against competitors to isolate the driver; dig into root cause; recommend 2–3 prioritised actions with impact estimates.' },
  { id: 'q-cs-03', category: 'Case/Guesstimate', sub: 'Case', prompt: 'Should an Indian D2C brand enter the Middle East?', answer: 'Market attractiveness (size, growth, diaspora demand, competition) → company capabilities (supply chain, brand fit) → entry mode (marketplace vs own site vs distributor) → economics (CAC, logistics, duties, payback) → risks. Recommendation with criteria and a pilot plan.' },
  { id: 'q-cs-04', category: 'Case/Guesstimate', sub: 'Product', prompt: 'Define a north-star metric for Spotify, LinkedIn or Zomato.', answer: 'It should capture delivered user value and lead revenue: Spotify — time spent listening per MAU; LinkedIn — weekly engaged members / meaningful connections; Zomato — successful orders delivered. List 3 input metrics and 1–2 guardrails.' },
  { id: 'q-cs-05', category: 'Case/Guesstimate', sub: 'Case', prompt: 'How would you price a new premium tier for an edtech app?', answer: 'Value-based (willingness to pay, surveys / Van Westendorp), competitor-based, cost-plus floor. Segment users, test 2–3 price points, watch conversion × ARPU and cannibalisation of the base tier.' },
  { id: 'q-cs-06', category: 'Case/Guesstimate', sub: 'Diagnostic', prompt: 'DAU is up but revenue is flat. Why might that be?', answer: 'Mix shift (growth in low-monetising segments / geographies), new users not yet converting, lower ARPU from discounts, ad fill/CPM falling, engagement in non-monetised surfaces, payment failures, or DAU inflated by bots / notification spam.' },
  { id: 'q-cs-07', category: 'Case/Guesstimate', sub: 'Product', prompt: 'What metrics would you track for a new UPI Lite-style feature?', answer: 'Adoption (activations / eligible users), usage (txns per active user, share of small-value payments), reliability (success rate, latency), retention (week-4 usage), business (cost per txn, server load saved), guardrails (fraud, complaints).' },
  { id: 'q-cs-08', category: 'Case/Guesstimate', sub: 'Metrics', prompt: 'Compute LTV and explain LTV:CAC.', answer: 'LTV ≈ ARPU × gross margin × expected lifetime (≈ 1 / monthly churn). LTV:CAC ≥ 3 is a common health bar; also track CAC payback months. Cohort-based LTV beats the simple formula.' },
  { id: 'q-cs-09', category: 'Case/Guesstimate', sub: 'Metrics', prompt: 'A retention curve flattens vs keeps declining to zero — what does each mean?', answer: 'Flattening = a core cohort keeps getting value (signal of product-market fit); improve the level and onboarding. Declining to zero = leaky bucket; growth spend is wasted until the product retains.' },
  { id: 'q-cs-10', category: 'Case/Guesstimate', sub: 'Diagnostic', prompt: 'Conversion fell after a website redesign. Roll back or not?', answer: 'Was it A/B tested? If not, compare like-for-like periods and segments (device, traffic source). Check tracking changes. Find the funnel step that broke. If impact is large and confirmed, roll back and re-launch behind an experiment.' },
  { id: 'q-cs-11', category: 'Case/Guesstimate', sub: 'Product', prompt: 'How would you measure the success of Instagram Reels?', answer: 'Goal (compete for short-video time, creator retention) → metrics: Reels watch time per DAU, % DAU watching, creators posting weekly, shares, ad revenue per Reels impression; guardrails: total app time, Feed/Stories engagement (cannibalisation), well-being reports.' },
  { id: 'q-cs-12', category: 'Case/Guesstimate', sub: 'Excel', prompt: 'VLOOKUP vs INDEX-MATCH vs XLOOKUP?', answer: 'VLOOKUP looks right only, breaks when columns are inserted, needs exact-match flag. INDEX-MATCH looks any direction and is robust. XLOOKUP (365) does both natively, with defaults for not-found, and can return arrays.' },

  // ───────────────────────── Behavioural ─────────────────────────
  { id: 'q-bh-01', category: 'Behavioural', prompt: 'Tell me about yourself.', answer: '90 seconds: present (final-year DS at VIT, what you build) → past proof (Outright internship + one metric, KYRO, Confer’s week-one traction, AWS SA) → future (why this role at this company). End with a hook they’ll ask about.' },
  { id: 'q-bh-02', category: 'Behavioural', prompt: 'Why data analytics / data science?', answer: 'A specific moment (the class-imbalance catch — numbers lie when you measure the wrong thing), plus markets/business interest: you like turning data into decisions. Tie to the role’s day-to-day.' },
  { id: 'q-bh-03', category: 'Behavioural', prompt: 'Why this company?', answer: 'Use the research template: one product insight, one recent news item, one tech/data detail, why the role fits your projects, and what you’d contribute in 6 months. Never generic.' },
  { id: 'q-bh-04', category: 'Behavioural', prompt: 'Tell me about a time you failed.', answer: 'Real failure, owned without excuses (e.g. two poor technical interviews), what you diagnosed, the system you built in response, and measurable change since. Learning > drama.' },
  { id: 'q-bh-05', category: 'Behavioural', prompt: 'Tell me about a conflict with a teammate.', answer: 'Disagreement on substance (approach / scope), how you listened and used data, what you conceded, the outcome and the relationship after. Show Have Backbone; Disagree and Commit.' },
  { id: 'q-bh-06', category: 'Behavioural', prompt: 'Tell me about a time you caught an error others missed.', answer: 'The Outright class-imbalance story: the headline accuracy, why you dug in, what precision/recall actually were, how you fixed evaluation, and the impact on the decision.' },
  { id: 'q-bh-07', category: 'Behavioural', prompt: 'Tell me about a time you changed your mind based on data.', answer: 'Initial belief, the evidence that contradicted it, how you updated, and the better outcome. Shows Are Right, A Lot.' },
  { id: 'q-bh-08', category: 'Behavioural', prompt: 'Describe a time you took ownership beyond your role.', answer: 'Something you didn’t have to do (e.g. building Confer’s payment flow end-to-end, or a test suite no one asked for), why, and the result.' },
  { id: 'q-bh-09', category: 'Behavioural', prompt: 'Tell me about a time you had to learn something fast.', answer: 'LangGraph for KYRO, or AWS SA-A — the deadline, how you learned (docs, building, tests), and what you shipped.' },
  { id: 'q-bh-10', category: 'Behavioural', prompt: 'What are your strengths and weaknesses?', answer: 'Strength with evidence (end-to-end builder: KYRO, Confer live). Real weakness with an active fix and progress (e.g. DSA under time pressure → structured practice + weekly mocks, with numbers).' },
  { id: 'q-bh-11', category: 'Behavioural', prompt: 'Where do you see yourself in 3 years?', answer: 'Deep in the domain you’re joining, owning analyses/models end-to-end that drive decisions, mentoring juniors. Ambitious but aligned with the role.' },
  { id: 'q-bh-12', category: 'Behavioural', prompt: 'Tell me about a time you dealt with ambiguity.', answer: 'Undefined problem (e.g. what "governance" should mean for KYRO, or scoping the Faculty Review project), how you framed it, made assumptions explicit, shipped an MVP, iterated.' },
  { id: 'q-bh-13', category: 'Behavioural', prompt: 'Describe a time you disagreed with a senior.', answer: 'Respectful, data-backed disagreement; you raised it once clearly, then committed to the decision — or changed it with evidence.' },
  { id: 'q-bh-14', category: 'Behavioural', prompt: 'What is your most impactful project?', answer: 'Pick per role: Analyst → Faculty Review Analytics / Outright; DS → Outright / NeuroLens; SDE → Confer; ML Eng → KYRO. Problem, your decisions, measurable result, what you’d do differently.' },
  { id: 'q-bh-15', category: 'Behavioural', prompt: 'How do you prioritise when everything is urgent?', answer: 'Impact × urgency, clarify with stakeholders, communicate trade-offs early, protect deep work. Example: hackathon or Confer launch week.' },
  { id: 'q-bh-16', category: 'Behavioural', prompt: 'Why should we hire you?', answer: 'Three proofs mapped to the JD’s top three requirements, plus a growth signal (the system you’re running now). Short and specific.' },
  { id: 'q-bh-17', category: 'Behavioural', prompt: 'Tell me about a time you simplified something complex.', answer: 'KYRO’s rule-first policy (deterministic rules handle most cases, the LLM only for the rest) or the VADER → Gemini cascade (cheap model first, expensive model only when needed).' },
  { id: 'q-bh-18', category: 'Behavioural', prompt: 'What questions do you have for us?', answer: 'Pick 3: what does success look like in 6 months; what data/tools the team uses daily; a recent analysis that changed a decision; how the team reviews work; what the interviewer enjoys most.' },
  { id: 'q-bh-19', category: 'Behavioural', prompt: 'What are your CTC expectations?', answer: 'For campus roles, defer to the company’s standard band. Off-campus: give a researched range anchored on the role and city, emphasise learning and fit, never the first lowball.' },
  { id: 'q-bh-20', category: 'Behavioural', prompt: 'Describe delivering under a tight deadline.', answer: 'Confer launch week or the HSBC hackathon: scope cut decisions, what you shipped, the result (100+ users / penultimate round), what you’d change.' },

  // ───────────────────────── Project deep-dives ─────────────────────────
  { id: 'q-pj-01', category: 'Project deep-dives', sub: 'KYRO', prompt: 'Walk me through KYRO’s architecture end to end.', answer: 'Cover: what problem (runtime governance of AI agents), the event path (agent action → FastAPI → async pipeline → decision engine), the three tiers (19 deterministic rules → session heuristics → Gemini judge), storage (MongoDB, Redis), live dashboard over WebSockets (Next.js), and the 27-test pytest suite. Draw it.' },
  { id: 'q-pj-02', category: 'Project deep-dives', sub: 'KYRO', prompt: 'Why a three-tier engine instead of just asking an LLM?', answer: 'Latency, cost, determinism and auditability: rules are instant, explainable and testable; heuristics catch session-level patterns; the LLM handles only genuinely ambiguous cases. Give the rough share of decisions each tier handles if you know it.' },
  { id: 'q-pj-03', category: 'Project deep-dives', sub: 'KYRO', prompt: 'What does "rule-dominant policy" mean and why did you choose it?', answer: 'When tiers disagree, a deterministic rule verdict wins over the LLM judge — the LLM can’t override a hard block. Safety and predictability over flexibility; LLM judges are biased and inconsistent.' },
  { id: 'q-pj-04', category: 'Project deep-dives', sub: 'KYRO', prompt: 'How did you test and evaluate KYRO? What do the 27 tests cover?', answer: 'Break the 27 tests down by area (rules, heuristics, pipeline, API) and explain how you tested the LLM tier (mocks, fixtures, golden cases). Be ready for: "how do you know the judge is right?"' },
  { id: 'q-pj-05', category: 'Project deep-dives', sub: 'KYRO', prompt: 'Why LangGraph? What did it give you over plain function calls?', answer: 'Explicit state machine / graph for multi-step flows, typed shared state, conditional edges, retries and checkpointing. Be honest about what was overkill.' },
  { id: 'q-pj-06', category: 'Project deep-dives', sub: 'KYRO', prompt: 'How does the async event pipeline work? What if Redis goes down?', answer: 'Explain producer → Redis (pub/sub or streams) → consumers → WebSocket broadcast. Failure: pub/sub is fire-and-forget (messages lost) — Redis Streams / Kafka give persistence and consumer groups; add retries, dead-letter queue, health checks.' },
  { id: 'q-pj-07', category: 'Project deep-dives', sub: 'KYRO', prompt: 'How would you scale KYRO to 10k events per second?', answer: 'Stateless FastAPI workers behind a load balancer, partitioned stream (Kafka) keyed by session, rules evaluated in-process, LLM tier behind a queue with rate limits and caching, MongoDB sharding / TTL collections, back-pressure and metrics.' },
  { id: 'q-pj-08', category: 'Project deep-dives', sub: 'KYRO', prompt: 'Hardest bug in KYRO, and what would you do differently?', answer: 'Prepare one concrete bug (async race, WebSocket reconnects, LLM JSON parsing) with how you found it. Differently: eval harness earlier, structured outputs, observability.' },
  { id: 'q-pj-09', category: 'Project deep-dives', sub: 'Confer', prompt: 'Walk me through Confer’s booking and payment flow.', answer: 'User picks expert + slot → hold slot → create Razorpay order server-side → client checkout → payment callback → verify signature on the server (never trust the client) → confirm booking → notify via Socket.io. Mention webhooks for reliability.' },
  { id: 'q-pj-10', category: 'Project deep-dives', sub: 'Confer', prompt: 'How do you prevent double-booking a slot?', answer: 'Atomic conditional update (findOneAndUpdate where status = free → held) or a unique index on (expertId, slotStart); short TTL hold released if payment fails; idempotent payment confirmation.' },
  { id: 'q-pj-11', category: 'Project deep-dives', sub: 'Confer', prompt: 'How did you get 100+ users and 15+ experts in week one?', answer: 'Be specific: channels used, who you onboarded first (supply side), what converted, what you measured. This is a growth story — great for analyst roles.' },
  { id: 'q-pj-12', category: 'Project deep-dives', sub: 'Confer', prompt: 'How does Socket.io fit in, and how would you scale real-time features?', answer: 'Real-time notifications / chat. Scaling: sticky sessions or a Redis adapter for multi-node pub/sub, rooms per booking, authentication on the handshake.' },
  { id: 'q-pj-13', category: 'Project deep-dives', sub: 'Confer', prompt: 'How is Confer deployed, and how do you manage secrets?', answer: 'Frontend on Netlify, backend containerised with Docker (state where it runs). Secrets in environment variables / a secrets manager — never in the repo; separate test and live Razorpay keys.' },
  { id: 'q-pj-14', category: 'Project deep-dives', sub: 'Faculty Review', prompt: 'Why VADER first, then Gemini? What is the routing rule?', answer: 'Cost/latency cascade: VADER is free and instant and handles clear-cut sentiment; ambiguous / low-confidence / mixed reviews go to Gemini. Explain the threshold you used and what share went to each stage.' },
  { id: 'q-pj-15', category: 'Project deep-dives', sub: 'Faculty Review', prompt: 'How did you validate sentiment accuracy on 1,200+ reviews?', answer: 'A hand-labelled sample, agreement between stages, precision/recall per class, error analysis (sarcasm, Hinglish, mixed reviews). If you didn’t, say what you’d do now.' },
  { id: 'q-pj-16', category: 'Project deep-dives', sub: 'Faculty Review', prompt: 'What insights did the dashboards surface, and who used them?', answer: 'Two or three concrete findings and the decision they could drive. Analyst interviewers care more about this than the model.' },
  { id: 'q-pj-17', category: 'Project deep-dives', sub: 'NeuroLens', prompt: 'Walk me through NeuroLens: data, model, results.', answer: 'Dataset (4 classes, size, source), preprocessing and augmentation, backbone + transfer-learning approach, metrics per class (not just accuracy), confusion matrix, Grad-CAM.' },
  { id: 'q-pj-18', category: 'Project deep-dives', sub: 'NeuroLens', prompt: 'What does Grad-CAM show, and did it change your trust in the model?', answer: 'Gradients of the class score w.r.t. the last conv feature maps → weighted heatmap of regions driving the prediction. Use it to check the model looks at the tumour, not artefacts / labels / borders.' },
  { id: 'q-pj-19', category: 'Project deep-dives', sub: 'NeuroLens', prompt: 'How did you avoid leakage (same patient in train and test)?', answer: 'Patient-level split if IDs exist; dedupe near-identical slices; augment only the training set. If the public dataset lacks IDs, acknowledge the risk.' },
  { id: 'q-pj-20', category: 'Project deep-dives', sub: 'Outright', prompt: 'What did you do at Outright Solutions? What was your biggest impact?', answer: 'Six-month DS internship: the problem, data, your pipeline, models, and the metric-level outcome. Lead with the class-imbalance catch.' },
  { id: 'q-pj-21', category: 'Project deep-dives', sub: 'Outright', prompt: 'Tell the class-imbalance story in full detail.', answer: 'Class ratio, the misleading accuracy number, how you noticed, metrics you switched to, the technique (weights / resampling / threshold), before-after numbers, and what the business did differently.' },
  { id: 'q-pj-22', category: 'Project deep-dives', sub: 'PySpark', prompt: 'Your PySpark pipeline: why Spark for this data, and what did tuning change?', answer: 'Honest about scale (learning + future scale), bronze/silver/gold design, what the Spark UI showed, before/after runtime from partitioning / broadcast / caching.' },
  { id: 'q-pj-23', category: 'Project deep-dives', sub: 'RAG', prompt: 'Your RAG project: chunking, retrieval and evaluation choices?', answer: 'Chunk size and why, embedding model, vector store, hybrid search + reranker, eval set size and the hit-rate / faithfulness numbers.' },
  { id: 'q-pj-24', category: 'Project deep-dives', sub: 'AWS', prompt: 'You’re AWS SA certified — how would you deploy KYRO on AWS?', answer: 'ECS Fargate (or App Runner) for FastAPI behind an ALB (WebSocket support), ElastiCache Redis, MongoDB Atlas / DocumentDB, Next.js on Amplify / CloudFront, Secrets Manager, CloudWatch logs + alarms, autoscaling on queue depth.' },
  { id: 'q-pj-25', category: 'Project deep-dives', sub: 'AWS', prompt: 'Design a daily batch analytics pipeline on AWS.', answer: 'Sources → S3 raw (partitioned by date) → Glue / EMR (PySpark) → S3 curated Parquet/Delta → Glue Catalog → Athena / Redshift → QuickSight. Orchestrate with Step Functions / MWAA; data-quality checks; IAM least privilege.' },
];

